function normalizeCRBrands(raw) {
  if (!raw) return [];
  let list = raw;
  if (Array.isArray(raw)) list = raw;
  else if (raw && typeof raw === "object") {
    if (Array.isArray(raw.brands)) list = raw.brands;
    else if (Array.isArray(raw.data)) list = raw.data;
    else if (Array.isArray(raw.items)) list = raw.items;
    else if (Array.isArray(raw.results)) list = raw.results;
    else if (Array.isArray(raw.families)) list = raw.families;
    else {
      const out = [];
      Object.keys(raw).forEach(k => {
        const v = raw[k];
        if (Array.isArray(v)) { v.forEach(x => out.push(x)); }
        else if (v && typeof v === "object") {
          if (v.name || v.brand_name || v.family_name || v.title || v.logo_url) out.push(v);
          else {
            Object.keys(v).forEach(k2 => {
              const v2 = v[k2];
              if (Array.isArray(v2)) v2.forEach(x => out.push(x));
              else if (v2 && typeof v2 === "object" && (v2.name || v2.brand_name)) out.push(v2);
            });
          }
        }
      });
      list = out;
    }
  }
  if (!Array.isArray(list)) return [];
  const seen = {};
  const result = [];
  list.forEach((b, i) => {
    if (!b || typeof b !== "object") return;
    const name = String(b.name || b.brand_name || b.family_name || b.title || b.brand || "").trim();
    if (!name || /^brand\s*\d+$/i.test(name)) return;
    const family = String(b.family_name || b.brand_name || b.name || name).trim();
    const key = family.toLowerCase();
    if (seen[key]) return;
    seen[key] = true;
    let logo = b.logo_url || b.logo || b.image || "";
    if (!logo && b.logo_base_url) logo = String(b.logo_base_url) + ".webp";
    result.push({
      id: String(b.id || b.slug || family) + "_" + i,
      name, family_name: family, brand_name: String(b.brand_name || family || name).trim(),
      logo, country_code: b.country_code || "", raw: b
    });
  });
  result.sort((a, b) => a.name.localeCompare(b.name));
  return result;
}

function normalizeCRProducts(raw, brandName) {
  if (!raw) return { fixed: [], ranges: [] };
  let list = raw;
  if (raw.products) list = raw.products;
  if (raw.data) list = raw.data;
  if (raw.items) list = raw.items;
  if (!Array.isArray(list) && typeof list === "object") {
    if (raw.denominations || raw.denomination || raw.face_values) list = [raw];
    else list = Object.values(list).filter(x => x && typeof x === "object");
  }
  if (!Array.isArray(list)) list = [];
  const fixed = [], ranges = [], seen = {};
  function addFixed(label, value, currency) {
    const v = Number(value);
    if (!isFinite(v) || v <= 0) return;
    const key = v.toFixed(2) + "|" + (currency || "");
    if (seen[key]) return;
    seen[key] = true;
    fixed.push({
      label: label || (currency ? (currency + " " + v) : ("$" + v)),
      value: v, denomination: label || (v + " " + (currency || "USD")), currency: currency || "USD"
    });
  }
  list.forEach(p => {
    const dens = p.denominations || p.denomination_list || p.face_values || p.values || p.amounts || [];
    if (Array.isArray(dens)) {
      dens.forEach(d => {
        if (d == null) return;
        if (typeof d === "number" || typeof d === "string") {
          const num = parseFloat(String(d).replace(/[^0-9.]/g, ""));
          addFixed(String(d), num, p.currency || "USD");
        } else if (typeof d === "object") {
          const num = parseFloat(d.value || d.face_value || d.amount || d.denomination || 0);
          const lab = d.label || d.denomination || d.localized || (d.currency ? (d.currency + " " + num) : null);
          addFixed(lab, num, d.currency || p.currency || "USD");
        }
      });
    }
    if (p.denomination && typeof p.denomination === "string" && p.denomination.toLowerCase() !== "range") {
      const num = parseFloat(String(p.denomination).replace(/[^0-9.]/g, ""));
      addFixed(p.denomination, num, p.currency || "USD");
    }
    if (p.face_value || p.value || p.amount) {
      const num = parseFloat(p.face_value || p.value || p.amount);
      addFixed(null, num, p.currency || "USD");
    }
    const isRange = String(p.denomination || p.type || p.kind || "").toLowerCase().indexOf("range") >= 0
      || p.min_value != null || p.max_value != null || p.min != null || p.max != null;
    if (isRange) {
      ranges.push({
        min: Number(p.min_value || p.min || 1) || 1,
        max: Number(p.max_value || p.max || 500) || 500,
        currency: p.currency || "USD",
        brand_name: p.brand_name || brandName
      });
    }
  });
  fixed.sort((a, b) => a.value - b.value);
  return { fixed, ranges };
}

const PTS_PER_USD = 1000;
function toUSD(pts) {
  const n = Number(pts);
  return isFinite(n) ? (n / PTS_PER_USD).toFixed(2) : "0.00";
}
function toPts(usd) {
  const n = Number(usd);
  return isFinite(n) ? Math.round(n * PTS_PER_USD) : 0;
}
function formatUSD(pts) {
  return "$" + toUSD(pts);
}

let audioCtx = null;
function playDing() {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === "suspended") audioCtx.resume();
    const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.connect(gain); gain.connect(audioCtx.destination);
    osc.type = "sine";
    osc.frequency.setValueAtTime(880, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(440, audioCtx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.25, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.35);
    osc.start(); osc.stop(audioCtx.currentTime + 0.35);
  } catch (e) {}
}

async function api(action, params = {}) {
  try {
    const qs = new URLSearchParams(Object.assign({ action }, params)).toString();
    const res = await fetch(SCRIPT_URL + "?" + qs);
    return await res.json();
  } catch (e) { return { error: "Network error" }; }
}
async function postApi(action, body = {}) {
  try {
    const params = new URLSearchParams();
    params.append("action", action);
    Object.keys(body).forEach(k => params.append(k, body[k]));
    const res = await fetch(SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
      body: params.toString()
    });
    return await res.json();
  } catch (e) { return { error: "Network error" }; }
}

